-- Read-model policy and KPI settings only. No transactions/customers are seeded.
CREATE TABLE IF NOT EXISTS ops_finance_policy(business_id TEXT PRIMARY KEY REFERENCES portfolio_businesses(id),source TEXT NOT NULL,evidence TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS ops_kpi_rules(business_id TEXT NOT NULL,metric_key TEXT NOT NULL,aggregation TEXT NOT NULL,evidence TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(business_id,metric_key),FOREIGN KEY(business_id,metric_key) REFERENCES bf_kpis(business_id,metric_key));
CREATE TABLE IF NOT EXISTS ops_kpi_targets(business_id TEXT NOT NULL,metric_key TEXT NOT NULL,start_day TEXT NOT NULL,end_day TEXT NOT NULL,target TEXT NOT NULL,direction TEXT NOT NULL,definition_revision INTEGER NOT NULL,rule_revision INTEGER NOT NULL,evidence TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(business_id,metric_key,start_day,end_day),FOREIGN KEY(business_id,metric_key) REFERENCES bf_kpis(business_id,metric_key),FOREIGN KEY(business_id,metric_key) REFERENCES ops_kpi_rules(business_id,metric_key));
CREATE TABLE IF NOT EXISTS ops_audit(id INTEGER PRIMARY KEY,actor TEXT NOT NULL,business_ref TEXT,event TEXT NOT NULL,outcome TEXT NOT NULL,agent TEXT,task_ref TEXT,created_at TEXT NOT NULL);
